*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #0f1117;
  --surface:     #1a1d27;
  --surface-2:   #22263a;
  --border:      #2e3250;
  --text:        #e2e6f3;
  --text-muted:  #7b82a8;
  --accent:      #6c7de8;
  --accent-hover:#8592f0;
  --danger:      #e85c5c;
  --danger-hover:#f07070;
  --focus-ring:  #6c7de8;
  --radius:      12px;
  --radius-sm:   8px;
  --transition:  180ms ease;
}

/* ── Base ── */
body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 999;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0.5rem; }

/* ── Layout ── */
header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

header svg { color: var(--accent); flex-shrink: 0; }

header h1 {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

main {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 3rem 1.5rem;
}

/* ── Image card ── */
.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 100%;
  max-width: 520px;
}

.image-preview {
  width: 100%;
  aspect-ratio: 4 / 3;
  display: block;
  object-fit: cover;
  background: var(--surface-2);
}

.image-card__body {
  padding: 1.25rem 1.5rem;
}

.image-card__meta {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  margin-bottom: 1.25rem;
}

.image-card__name {
  font-size: 1rem;
  font-weight: 600;
}

.image-card__info {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.image-card__actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* ── Buttons ── */
button, [role="button"] {
  cursor: pointer;
  font: inherit;
  border: none;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 1.1rem;
  font-size: 0.875rem;
  font-weight: 500;
  transition:
    background var(--transition),
    color var(--transition),
    box-shadow var(--transition);
}

button:focus-visible {
  outline: 2.5px solid var(--focus-ring);
  outline-offset: 3px;
}

/* Secondary / ghost */
.btn-secondary {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn-secondary:hover {
  background: var(--border);
}

/* Danger / delete trigger */
.btn-danger {
  background: transparent;
  color: var(--danger);
  border: 1px solid var(--danger);
}
.btn-danger:hover {
  background: color-mix(in srgb, var(--danger) 12%, transparent);
  color: var(--danger-hover);
  border-color: var(--danger-hover);
}

/* Primary */
.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-hover); }

/* ── Modal dialog ── */
dialog {
  /* Reset browser defaults */
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0;
  width: min(92vw, 440px);
  box-shadow:
    0 8px 32px rgba(0,0,0,0.55),
    0 1.5px 4px rgba(0,0,0,0.35);

  /* Start hidden – browser toggles this with showModal() */
}

dialog::backdrop {
  background: rgba(5, 6, 14, 0.75);
  backdrop-filter: blur(3px);
}

/* Animate in */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] {
    animation: dialog-in 220ms cubic-bezier(0.16, 1, 0.3, 1) both;
  }
  @keyframes dialog-in {
    from { opacity: 0; transform: translateY(-10px) scale(0.97); }
    to   { opacity: 1; transform: none; }
  }
}

.dialog__header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.5rem 1.5rem 0;
}

.dialog__icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  background: color-mix(in srgb, var(--danger) 15%, transparent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--danger);
}

.dialog__title {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.3;
  margin-top: 0.5rem;
}

.dialog__body {
  padding: 0.75rem 1.5rem 1.5rem;
  /* offset so body text aligns with title when icon is present */
  padding-left: calc(1.5rem + 40px + 1rem);
}

.dialog__body p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.65;
}

.dialog__body .image-name {
  color: var(--text);
  font-weight: 500;
}

.dialog__footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  border-radius: 0 0 var(--radius) var(--radius);
}

/* Destructive confirm button */
.btn-confirm-delete {
  background: var(--danger);
  color: #fff;
}
.btn-confirm-delete:hover {
  background: var(--danger-hover);
}

/* ── Footer ── */
footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  text-align: center;
  padding: 0.875rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ── Reflow: narrow viewports ── */
@media (max-width: 360px) {
  .dialog__body { padding-left: 1.5rem; }
  .dialog__footer { flex-direction: column-reverse; }
  .dialog__footer button { width: 100%; justify-content: center; }
}
