+  padding: 0.5rem 1rem;
+  background: var(--accent);
+  color: #fff;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  z-index: 999;
+  text-decoration: none;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 0.5rem; }
