+  width: 100%;
+  aspect-ratio: 4 / 3;
+  display: block;
+  object-fit: cover;
+  background: var(--surface-2);
+}
+
+.image-card__body {
+  padding: 1.25rem 1.5rem;
+}
+
+.image-card__meta {
+  display: flex;
+  flex-direction: column;
+  gap: 0.2rem;
+  margin-bottom: 1.25rem;
+}
+
+.image-card__name {
+  font-size: 1rem;
+  font-weight: 600;
+}
+
+.image-card__info {
+  font-size: 0.8125rem;
+  color: var(--text-muted);
+}
+
+.image-card__actions {
+  display: flex;
+  gap: 0.75rem;
+  flex-wrap: wrap;
+}
+
