const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the page from file
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css', 'utf8');
  const js   = fs.readFileSync('app.js', 'utf8');

  // Inline everything into one page for testing
  const combined = html
    .replace('<link rel=\"stylesheet\" href=\"styles.css\" />', '<style>' + css + '</style>')
    .replace('<script src=\"app.js\"></script>', '<script>' + js + '</script>');

  await page.setContent(combined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const r = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, nodes: v.nodes.map(n => ({ target: n.target, html: n.html, failureSummary: n.failureSummary })) })),
    bp:   bp.map(v =>   ({ id: v.id, impact: v.impact, description: v.description, nodes: v.nodes.map(n => ({ target: n.target, html: n.html, failureSummary: n.failureSummary })) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
