  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--danger);
}

.dialog__title {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.3;
  margin-top: 0.5rem;
}

.dialog__body {
  padding: 0.75rem 1.5rem 1.5rem;
  /* offset so body text aligns with title when icon is present */
  padding-left: calc(1.5rem + 40px + 1rem);
}

.dialog__body p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.65;
}

.dialog__body .image-name {
  color: var(--text);
  font-weight: 500;
}

.dialog__footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  border-radius: 0 0 var(--radius) var(--radius);
}

/* Destructive confirm button */
.btn-confirm-delete {
  background: var(--danger);
  color: #fff;
}
.btn-confirm-delete:hover {
  background: var(--danger-hover);
}

/* ── Footer ── */
footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  text-align: center;
  padding: 0.875rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ── Reflow: narrow viewports ── */
@media (max-width: 360px) {
  .dialog__body { padding-left: 1.5rem; }
  .dialog__footer { flex-direction: column-reverse; }
  .dialog__footer button { width: 100%; justify-content: center; }
}
